        statements (dict): Mapping from participant names to lists of their statements.
        days_of_week (set): Set of day names to ignore in the statements.

    Returns:
        bool: True if scenario is consistent, False otherwise.
    """
    # Helper to determine truth of a statement relative to the scenario
    def evaluate_statement(stmt, speaker):
        stmt = stmt.strip()
        # Ignore statements containing any day of the week (case insensitive)
        upper_stmt = stmt.upper()
        if any(day in upper_stmt for day in days_of_week):
            return None  # ignore

        # Remove trailing period for easier parsing
        stmt_no_period = stmt.rstrip('.')
        parts = stmt_no_period.split()

        # Pattern: "I am guilty" or "I am not guilty"
        if parts[0].lower() == "i":
            target = speaker
            if len(parts) >= 3 and parts[1].lower() == "am":
                if parts[2].lower() == "guilty":
                    return target == scenario
                if len(parts) >= 4 and parts[2].lower() == "not" and parts[3].lower() == "guilty":
                    return target != scenario

        # Pattern: "NAME is guilty" or "NAME is not guilty"
        if len(parts) >= 3 and parts[1].lower() == "is":
            target = parts[0]
            if parts[2].lower() == "guilty":
                return target == scenario
            if len(parts) >= 4 and parts[2].lower() == "not" and parts[3].lower() == "guilty":
                return target != scenario

        # If statement doesn't match known patterns, ignore it
        return None

    for speaker, stmt_list in statements.items():
        for stmt in stmt_list:
            truth = evaluate_statement(stmt, speaker)
            if truth is None:
                continue  # ignored or unrecognized statement

            if speaker in liar_count:
                # Liars should state false truths
                if truth:
                    return False
            else:
                # Non-liars should state true truths
                if not truth:
                    return False
    return True

