def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    # Normalize names for comparison
    scenario_name = scenario.strip()
    # Helper to determine if a statement references a day of week
    def is_day_statement(stmt: str) -> bool:
        for day in days_of_week:
            if day.lower() in stmt.lower():
                return True
        return False

    # Evaluate each statement
    for speaker, stmts in statements.items():
        speaker_name = speaker.strip()
        for raw_stmt in stmts:
            stmt = raw_stmt.strip()
            # Skip day-of-week statements
            if is_day_statement(stmt):
                continue

            stmt_lower = stmt.lower().strip('.')
            truth = None

            # Match patterns
            # I am guilty
            match = re.match(r'i am guilty', stmt_lower)
            if match:
                truth = (speaker_name == scenario_name)
            # I am not guilty
            match = re.match(r'i am not guilty', stmt_lower)
            if match:
                truth = (speaker_name != scenario_name)
            # X is guilty
            match = re.match(r'(.+?) is guilty', stmt_lower)
            if match and truth is None:
                subject = match.group(1).strip()
                truth = (subject == scenario_name)
            # X is not guilty
            match = re.match(r'(.+?) is not guilty', stmt_lower)
            if match and truth is None:
                subject = match.group(1).strip()
                truth = (subject != scenario_name)

            # If statement doesn't match any known pattern, skip it
            if truth is None:
                continue

            # Validate truth according to liar status
            if speaker_name in liar_count:
                if truth:
                    return False  # liar should not make true statement
            else:
                if not truth:
                    return False  # truth teller should not make false statement
    return True

