def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for ai in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0] % MOD
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            left = j - ai - 1
            if left >= 0:
                val = prefix[j] - prefix[left]
            else:
                val = prefix[j]
            new_dp[j] = val % MOD
        dp = new_dp
    return dp[m] % MOD

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        limit = a[i]
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j-1] + dp[j]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                val = prefix[j]
            else:
                val = (prefix[j] - prefix[low-1]) % MOD
            new_dp[j] = val
        dp = new_dp
    return dp[m] % MOD

def find_most_unhappy_day(schedule) -> int:
    max_over = 0
    most_unhappy_day = 0
    for i, (school, extra) in enumerate(schedule):
        total = school + extra
        if total > 8:
            over = total - 8
            if over > max_over:
                max_over = over
                most_unhappy_day = i + 1
    return most_unhappy_day

